            sysmsg, sess_ts, msgs = read_events(st["events_file"])
            if not msgs or not sysmsg:
                log("SKIP (no agent_end/system)", run["run_id"], sk)
                continue
            steps.append(dict(run=run["run_id"], arm=arm, step=int(sk), st=st, sysmsg=sysmsg,
